const errors = [];
const round = (x, d = 2) => (x === null || x === undefined || !Number.isFinite(x)) ? null : Math.round(x * 10 ** d) / 10 ** d;
const toNum = (v) => {
  if (v === null || v === undefined || String(v).trim() === '') return null;
  const n = Number(String(v).replace(/,/g, '').trim());
  return Number.isFinite(n) ? n : null;
};
const errMsg = (json) => {
  const e = json && json.error;
  if (!e) return null;
  return typeof e === 'string' ? e : (e.message || e.description || JSON.stringify(e));
};

// 날짜순으로 정렬해 최신값, 전일 대비, 20일 평균 대비를 계산
function summarize(points) {
  const pts = points
    .filter(p => p && p.date && Number.isFinite(p.value))
    .sort((a, b) => a.date.localeCompare(b.date));
  if (!pts.length) return null;
  const last = pts[pts.length - 1];
  const prev = pts.length > 1 ? pts[pts.length - 2] : null;
  const recent = pts.slice(-20);
  const ma20 = recent.length === 20 ? recent.reduce((s, p) => s + p.value, 0) / 20 : null;
  return {
    value: round(last.value),
    date: last.date,
    change: prev ? round(last.value - prev.value) : null,
    changePct: prev ? round((last.value / prev.value - 1) * 100) : null,
    ma20: round(ma20),
    vsMa20Pct: ma20 ? round((last.value / ma20 - 1) * 100) : null,
  };
}

// 1) 환율: Frankfurter(유럽중앙은행 기준, 달러 기준)를 원화 기준으로 환산
const fx = { usdKrw: null, jpyKrw100: null, cnyKrw: null, eurKrw: null };
const fxJson = $('환율 조회').first().json;
if (errMsg(fxJson)) {
  errors.push(`환율 조회: ${errMsg(fxJson)}`);
} else {
  const series = { usdKrw: [], jpyKrw100: [], cnyKrw: [], eurKrw: [] };
  for (const [date, r] of Object.entries(fxJson.rates || {})) {
    if (!r || !r.KRW) continue;
    series.usdKrw.push({ date, value: r.KRW });
    if (r.JPY) series.jpyKrw100.push({ date, value: (r.KRW / r.JPY) * 100 });
    if (r.CNY) series.cnyKrw.push({ date, value: r.KRW / r.CNY });
    if (r.EUR) series.eurKrw.push({ date, value: r.KRW / r.EUR });
  }
  for (const key of Object.keys(series)) fx[key] = summarize(series[key]);
  if (!fx.usdKrw) errors.push('환율 조회: 데이터 없음');
}

// 2) 미국 지표: FRED CSV(observation_date,값). 휴장일은 빈칸이나 '.'
function parseFred(nodeName) {
  const json = $(nodeName).first().json;
  if (errMsg(json)) {
    errors.push(`${nodeName}: ${errMsg(json)}`);
    return null;
  }
  const lines = String(json.data || '').trim().split(String.fromCharCode(10)).slice(1);
  const points = lines.map((line) => {
    const [date, raw] = line.trim().split(',');
    return { date: (date || '').trim(), value: raw && raw.trim() !== '.' ? toNum(raw) : null };
  });
  const result = summarize(points);
  if (!result) errors.push(`${nodeName}: 데이터 없음`);
  return result;
}
const us = {
  sp500: parseFred('S&P500 조회'),
  nasdaq: parseFred('NASDAQ 조회'),
  us10y: parseFred('미국 10년물 금리 조회'),
  vix: parseFred('VIX 조회'),
};

// 3) 국내 지수: KRX 날짜별 응답에서 대표 지수 행만 사용
function parseKrx(nodeName, indexName) {
  const points = [];
  let firstError = null;
  for (const item of $(nodeName).all()) {
    const json = item.json || {};
    const error = errMsg(json) || (json.respCode && String(json.respCode) !== '200' ? `${json.respCode} ${json.respMsg || ''}`.trim() : null);
    if (error) {
      firstError = firstError || error;
      continue;
    }
    const rows = Array.isArray(json.OutBlock_1) ? json.OutBlock_1 : [];
    const clean = (s) => String(s || '').split(' ').join('');
    const row = rows.find(r => clean(r.IDX_NM) === indexName) || rows.find(r => clean(r.IDX_NM) === `${indexName}지수`);
    if (!row) continue;
    const d = String(row.BAS_DD || '');
    points.push({ date: `${d.slice(0, 4)}-${d.slice(4, 6)}-${d.slice(6, 8)}`, value: toNum(row.CLSPRC_IDX) });
  }
  const result = summarize(points);
  if (!result) errors.push(`${nodeName}: ${firstError || `'${indexName}' 데이터 없음`}`);
  return result;
}
const kr = {
  kospi: parseKrx('KOSPI 지수 조회', '코스피'),
  kosdaq: parseKrx('KOSDAQ 지수 조회', '코스닥'),
};

// 4) 사람이 읽는 요약 줄 (AI 프롬프트·브리핑용)
const fmt = (x) => (x === null || x === undefined) ? '-' : x.toLocaleString('en-US', { maximumFractionDigits: 2 });
const signed = (x, unit) => (x === null || x === undefined) ? '-' : `${x > 0 ? '+' : ''}${fmt(x)}${unit}`;
const monthDay = (date) => date ? `${Number(date.slice(5, 7))}/${Number(date.slice(8, 10))}` : '';
const line = (label, s, unit = '', pointChange = false) => {
  if (!s) return `${label}: 정보 없음`;
  const change = pointChange ? signed(s.change, '%p') : signed(s.changePct, '%');
  const ma = s.ma20 === null ? '' : (pointChange ? `, 20일 평균 ${fmt(s.ma20)}${unit}` : `, 20일 평균 대비 ${signed(s.vsMa20Pct, '%')}`);
  return `${label}: ${fmt(s.value)}${unit} (전일 대비 ${change}${ma}) · ${monthDay(s.date)}`;
};
const summaryLines = [
  line('원/달러', fx.usdKrw, '원'),
  line('원/100엔', fx.jpyKrw100, '원'),
  line('원/위안', fx.cnyKrw, '원'),
  line('원/유로', fx.eurKrw, '원'),
  line('KOSPI', kr.kospi),
  line('KOSDAQ', kr.kosdaq),
  line('S&P500', us.sp500),
  line('NASDAQ', us.nasdaq),
  line('미국 10년물 금리', us.us10y, '%', true),
  line('VIX', us.vix),
];

const summaryText = summaryLines.join(`
`);

return [{ json: { fx, kr, us, summaryLines, summaryText, errors, asOf: $now.toISO() } }];
